         background: var(--error-bg);
       }

       .helper-text {
         color: var(--muted);
         font-size: 0.9rem;
         line-height: 1.45;
       }

       .error-text {
         color: var(--error);
         font-size: 0.92rem;
         line-height: 1.45;
       }

       .actions {
         display: flex;
         justify-content: flex-start;
         margin-top: 6px;
       }

       button {
         appearance: none;
         border: 0;
         border-radius: 14px;
         padding: 14px 20px;
         background: var(--primary);
         color: white;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 10px 24px rgba(37, 99, 235, 0.25);
         transition:
           transform 0.15s ease,
           background-color 0.2s ease;
       }

       button:hover {
         background: var(--primary-hover);
       }

       button:active {
         transform: translateY(1px);
       }

       .status {
         margin-top: 16px;
         padding: 12px 14px;
         border-radius: 14px;
         background: #ecfeff;
         color: #155e75;
         display: none;
       }

       .status.is-visible {
         display: block;
       }

       @media (max-width: 640px) {
         .support-card {
           padding: 24px;
         }
       }
     </style>
   </head>
   <body>
     <div id="root"></div>

     <script>
       const state = {
         values: {
           fullName: "",
           email: "",
           phone: "",
         },
         touched: {
           fullName: false,
           email: false,
           phone: false,
         },
         submitted: false,
         success: false,
       };

       const root = document.getElementById("root");

       const escapeHtml = (value) =>
         value
           .replace(/&/g, "&amp;")
           .replace(/</g, "&lt;")
           .replace(/>/g, "&gt;")
           .replace(/"/g, "&quot;")
           .replace(/'/g, "&#39;");

       function validate(values) {
         const errors = {};
         const fullName = values.fullName.trim();
         const email = values.email.trim();
         const phone = values.phone.trim();

         if (!fullName) {
           errors.fullName = "Full name is required.";
         }

         if (!email) {
           errors.email = "Email address is required.";
         } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
           errors.email = "Enter a valid email address.";
         }

         if (phone && !/^\+?[0-9()\-\s]{7,}$/.test(phone)) {
           errors.phone = "Enter a valid phone number or leave this field blank.";
         }

         return errors;
       }

       function fieldId(name) {
         return `contact-${name}`;
       }

       function errorId(name) {
         return `${fieldId(name)}-error`;
       }

       function helperId(name) {
         return `${fieldId(name)}-help`;
       }

       function TextField({ name, label, type, value, required, placeholder, helperText, error }) {
         const describedBy = [helperText ? helperId(name) : null, error ? errorId(name) : null]
           .filter(Boolean)
           .join(" ");

         return `
           <div class="form-field">
             <label for="${fieldId(name)}">
               ${escapeHtml(label)}${required ? '<span class="required-indicator" aria-hidden="true">*</span>' : ""}
             </label>
             <input
               id="${fieldId(name)}"
               name="${name}"
               type="${type}"
               value="${escapeHtml(value)}"
               placeholder="${escapeHtml(placeholder)}"
               ${required ? "required" : ""}
               aria-required="${required ? "true" : "false"}"
               aria-invalid="${error ? "true" : "false"}"
               ${describedBy ? `aria-describedby="${describedBy}"` : ""}
             />
             ${helperText ? `<div class="helper-text" id="${helperId(name)}">${escapeHtml(helperText)}</div>` : ""}
             ${error ? `<div class="error-text" id="${errorId(name)}" role="alert">${escapeHtml(error)}</div>` : ""}
           </div>
         `;
       }

       function App() {
         const errors = state.submitted || state.touched.fullName || state.touched.email || state.touched.phone
           ? validate(state.values)
           : {};

         return `
           <main class="page-shell">
             <section class="support-card" aria-labelledby="support-form-title">
               <p class="eyebrow">Support</p>
               <h1 id="support-form-title">Contact our team</h1>
               <p class="lead">Send us your details and we&apos;ll get back to you as soon as possible.</p>

               <form novalidate>
                 ${TextField({
                   name: "fullName",
                   label: "Full name",
                   type: "text",
                   value: state.values.fullName,
                   required: true,
                   placeholder: "Jane Doe",
                   helperText: "",
                   error: errors.fullName,
                 })}
                 ${TextField({
                   name: "email",
                   label: "Email address",
                   type: "email",
                   value: state.values.email,
                   required: true,
                   placeholder: "jane@company.com",
                   helperText: "",
                   error: errors.email,
                 })}
                 ${TextField({
                   name: "phone",
                   label: "Phone number",
                   type: "tel",
                   value: state.values.phone,
                   required: false,
                   placeholder: "+1 (555) 123-4567",
                   helperText: "Optional. Use a format like +1 (555) 123-4567 or 555-123-4567.",
                   error: errors.phone,
                 })}

                 <div class="actions">
                   <button type="submit">Send message</button>
                 </div>

                 <div class="status ${state.success ? "is-visible" : ""}" aria-live="polite">
                   Thanks — your message is ready to send.
                 </div>
               </form>
             </section>
           </main>
         `;
       }

       function render() {
         root.innerHTML = App();
         const form = root.querySelector("form");
         const inputs = form.querySelectorAll("input");

         inputs.forEach((input) => {
           input.addEventListener("input", onInput);
           input.addEventListener("blur", onBlur);
         });

         form.addEventListener("submit", onSubmit);
       }

       function syncValue(name, value) {
         state.values[name] = value;
         state.success = false;
       }

       function onInput(event) {
         const { name, value } = event.target;
         syncValue(name, value);
         state.touched[name] = true;
         render();
       }

       function onBlur(event) {
         state.touched[event.target.name] = true;
         render();
       }

       function onSubmit(event) {
         event.preventDefault();
         state.submitted = true;

         const errors = validate(state.values);
         if (Object.keys(errors).length > 0) {
           state.success = false;
           render();
           const firstInvalid = root.querySelector('[aria-invalid="true"]');
           if (firstInvalid) firstInvalid.focus();
           return;
         }

         state.success = true;
         render();
       }

       render();
     </script>
   </body>
 </html>

')
